    13	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    14	                                         String guestCpf, String companyCnpj, String companyName,
    15	                                         String guestPassport, String guestCountry,
    16	                                         LocalDate checkIn, LocalDate checkOut, int guests,
    17	                                         RatePlan ratePlan) {
    18	        Reservation reservation = new Reservation();
    19	        reservation.setId(nextReservationId++);
    20	        reservation.setRoomNumber(roomNumber);
    21	        reservation.setGuestName(guestName);
    22	        reservation.setGuestEmail(guestEmail);
    23	        reservation.setGuestCpf(guestCpf);
