    27	        reservation.setGuestCountry(guestCountry);
    28	        reservation.setCheckIn(checkIn);
    29	        reservation.setCheckOut(checkOut);
    30	        reservation.setGuests(guests);
    31	        reservation.setRatePlan(ratePlan);
    32	
    33	        Room room = roomService.getRoomByNumber(roomNumber);
    34	        int nights = PriceService.calculateNights(checkIn, checkOut);
    35	        BigDecimal subtotal = PriceService.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
    36	        BigDecimal discount = PriceService.calculateDiscount(subtotal, ratePlan.getValue());
    37	        BigDecimal total = PriceService.calculateTotal(subtotal, discount);
    38	
    39	        reservation.setNights(nights);
    40	        reservation.setSubtotal(subtotal);
    41	        reservation.setDiscount(discount);
    42	        reservation.setTotal(total);
    43	        reservation.setStatus(ReservationStatus.PENDING);
    44	        reservation.setAmountPaid(BigDecimal.ZERO);
    45	        reservation.setRefund(null);
    46	
    47	        reservations.put(reservation.getId(), reservation);
    48	        return reservation;
    49	    }
