    55	    public Reservation confirmReservation(long id) {
    56	        Reservation reservation = reservations.get(id);
    57	        if (reservation != null && reservation.getStatus() == ReservationStatus.PENDING) {
    58	            reservation.setStatus(ReservationStatus.CONFIRMED);
    59	            reservation.setAmountPaid(reservation.getTotal());
    60	        }
    61	        return reservation;
    62	    }
