    64	    public Reservation checkIn(long id) {
    65	        Reservation reservation = reservations.get(id);
    66	        if (reservation != null && reservation.getStatus() == ReservationStatus.CONFIRMED) {
    67	            reservation.setStatus(ReservationStatus.CHECKED_IN);
    68	        }
    69	        return reservation;
    70	    }
    71	
    72	    public Reservation checkOut(long id) {
    73	        Reservation reservation = reservations.get(id);
    74	        if (reservation != null && reservation.getStatus() == ReservationStatus.CHECKED_IN) {
    75	            reservation.setStatus(ReservationStatus.CHECKED_OUT);
    76	        }
    77	        return reservation;
    78	    }
    79	
    80	    public Reservation cancelReservation(long id) {
    81	        Reservation reservation = reservations.get(id);
    82	        if (reservation != null &&
    83	            (reservation.getStatus() == ReservationStatus.PENDING ||
    84	             reservation.getStatus() == ReservationStatus.CONFIRMED)) {
    85	
    86	            ReservationStatus previousStatus = reservation.getStatus();
    87	            reservation.setStatus(ReservationStatus.CANCELLED);
    88	
    89	            if (previousStatus == ReservationStatus.CONFIRMED) {
    90	                if (reservation.getRatePlan() == RatePlan.STANDARD) {
    91	                    reservation.setRefund(reservation.getAmountPaid());
    92	                } else {
    93	                    reservation.setRefund(BigDecimal.ZERO);
    94	                }
    95	            } else {
    96	                reservation.setRefund(BigDecimal.ZERO);
    97	            }
    98	        }
    99	        return reservation;
   100	    }
   101	
   102	    public boolean isRoomAvailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
   103	        for (Reservation res : reservations.values()) {
   104	            if (res.getRoomNumber() == roomNumber && res.getStatus() != ReservationStatus.CANCELLED) {
   105	                LocalDate resCheckIn = res.getCheckIn();
   106	                LocalDate resCheckOut = res.getCheckOut();
   107	
   108	                if (checkIn.isBefore(resCheckOut) && checkOut.isAfter(resCheckIn)) {
   109	                    return false;
   110	                }
   111	            }
   112	        }
   113	        return true;
   114	    }
   115	
   116	    public Collection<Reservation> getAllReservations() {
   117	        return reservations.values();
