     7	public class PriceService {
     8	
     9	    public static boolean isHighSeason(LocalDate date) {
    10	        int month = date.getMonthValue();
    11	        int day = date.getDayOfMonth();
    12	
    13	        if (month == 7) {
    14	            return true;
    15	        }
    16	
    17	        if (month == 12) {
    18	            return day >= 15;
    19	        }
    20	
    21	        if (month == 1 || month == 2) {
    22	            return true;
    23	        }
    24	
    25	        return false;
    26	    }
    27	
    28	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
    29	        if (isHighSeason(date)) {
    30	            BigDecimal rate = baseRate.multiply(new BigDecimal("1.20"));
    31	            return rate.setScale(2, RoundingMode.HALF_EVEN);
    32	        }
    33	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
    34	    }
    35	
    36	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    37	        BigDecimal subtotal = BigDecimal.ZERO;
    38	        LocalDate current = checkIn;
    39	
    40	        while (current.isBefore(checkOut)) {
    41	            BigDecimal nightRate = calculateNightlyRate(baseRate, current);
    42	            subtotal = subtotal.add(nightRate);
    43	            current = current.plusDays(1);
    44	        }
    45	
    46	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
    47	    }
    48	
    49	    public static BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
    50	        if ("NON_REFUNDABLE".equals(ratePlan)) {
    51	            BigDecimal discount = subtotal.multiply(new BigDecimal("0.15"));
    52	            return discount.setScale(2, RoundingMode.HALF_EVEN);
    53	        }
    54	        return BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
    55	    }
    56	
    57	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    58	        BigDecimal total = subtotal.subtract(discount);
    59	        return total.setScale(2, RoundingMode.HALF_EVEN);
    60	    }
    61	
    62	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
    63	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    64	    }
    65	
    66	    public static BigDecimal calculateISS(BigDecimal total) {
    67	        BigDecimal iss = total.multiply(new BigDecimal("0.05"));
    68	        return iss.setScale(2, RoundingMode.HALF_EVEN);
    69	    }
    70	}
