    87	
    88	    public String getOccupancyReport(LocalDate date) {
    89	        StringBuilder csv = new StringBuilder();
    90	        csv.append("room,type,reservation,check_in,check_out\n");
    91	
    92	        List<Reservation> occupiedRooms = new ArrayList<>();
    93	        for (Reservation res : reservationService.getAllReservations()) {
    94	            if (res.getStatus() != ReservationStatus.CANCELLED &&
    95	                (res.getStatus() == ReservationStatus.CONFIRMED ||
    96	                 res.getStatus() == ReservationStatus.CHECKED_IN ||
    97	                 res.getStatus() == ReservationStatus.CHECKED_OUT)) {
    98	
    99	                if (res.getCheckIn().isBefore(date.plusDays(1)) && res.getCheckOut().isAfter(date)) {
   100	                    occupiedRooms.add(res);
   101	                }
   102	            }
   103	        }
   104	
   105	        occupiedRooms.sort((a, b) -> Integer.compare(a.getRoomNumber(), b.getRoomNumber()));
   106	
   107	        for (Reservation res : occupiedRooms) {
   108	            Room room = roomService.getRoomByNumber(res.getRoomNumber());
   109	            csv.append(res.getRoomNumber()).append(",");
   110	            csv.append(room.getType()).append(",");
   111	            csv.append(res.getId()).append(",");
   112	            csv.append(res.getCheckIn().format(DateTimeFormatter.ISO_DATE)).append(",");
   113	            csv.append(res.getCheckOut().format(DateTimeFormatter.ISO_DATE)).append("\n");
   114	        }
   115	
   116	        csv.append("total,").append(occupiedRooms.size()).append("/5\n");
   117	
   118	        return csv.toString();
   119	    }
   120	
   121	    public String getRevenueReport(YearMonth month) {
   122	        StringBuilder csv = new StringBuilder();
   123	        csv.append("reservation,room,check_in,check_out,status,amount\n");
   124	
   125	        List<Reservation> monthlyReservations = new ArrayList<>();
   126	        for (Reservation res : reservationService.getAllReservations()) {
   127	            if (YearMonth.from(res.getCheckIn()).equals(month) &&
   128	                res.getStatus() != ReservationStatus.PENDING &&
   129	                res.getStatus() != ReservationStatus.CANCELLED) {
   130	                monthlyReservations.add(res);
   131	            } else if (res.getStatus() == ReservationStatus.CANCELLED &&
   132	                       YearMonth.from(res.getCheckIn()).equals(month) &&
   133	                       res.getRatePlan() == RatePlan.NON_REFUNDABLE) {
   134	                monthlyReservations.add(res);
   135	            }
   136	        }
   137	
   138	        monthlyReservations.sort((a, b) -> {
   139	            int dateCompare = a.getCheckIn().compareTo(b.getCheckIn());
   140	            if (dateCompare != 0) return dateCompare;
   141	            return Long.compare(a.getId(), b.getId());
   142	        });
   143	
   144	        BigDecimal total = BigDecimal.ZERO;
   145	        for (Reservation res : monthlyReservations) {
   146	            csv.append(res.getId()).append(",");
   147	            csv.append(res.getRoomNumber()).append(",");
   148	            csv.append(res.getCheckIn().format(DateTimeFormatter.ISO_DATE)).append(",");
   149	            csv.append(res.getCheckOut().format(DateTimeFormatter.ISO_DATE)).append(",");
   150	            csv.append(res.getStatus().getValue()).append(",");
   151	
   152	            BigDecimal amount = BigDecimal.ZERO;
   153	            if (res.getStatus() == ReservationStatus.CONFIRMED ||
   154	                res.getStatus() == ReservationStatus.CHECKED_IN ||
   155	                res.getStatus() == ReservationStatus.CHECKED_OUT) {
   156	                amount = res.getAmountPaid();
   157	            } else if (res.getStatus() == ReservationStatus.CANCELLED && res.getRatePlan() == RatePlan.NON_REFUNDABLE) {
   158	                amount = res.getAmountPaid();
   159	            }
   160	
   161	            if (res.getRefund() != null && res.getRefund().compareTo(BigDecimal.ZERO) > 0) {
   162	                amount = amount.subtract(res.getRefund());
   163	            }
   164	
   165	            csv.append(String.format("%.2f", amount)).append("\n");
   166	            total = total.add(amount);
   167	        }
   168	
   169	        csv.append("total,,,,").append(String.format("%.2f", total)).append("\n");
   170	
   171	        return csv.toString();
   172	    }
   173	}
