    28	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
    29	        if (isHighSeason(date)) {
    30	            BigDecimal rate = baseRate.multiply(new BigDecimal("1.20"));
    31	            return rate.setScale(2, RoundingMode.HALF_EVEN);
    32	        }
    33	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
    34	    }
